import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Do1fvF3d.js";const g=JSON.parse('{"title":"How it is built","description":"","frontmatter":{},"headers":[],"relativePath":"en/proyecto/arquitectura.md","filePath":"en/proyecto/arquitectura.md","lastUpdated":null}'),o={name:"en/proyecto/arquitectura.md"};function n(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="how-it-is-built" tabindex="-1">How it is built <a class="header-anchor" href="#how-it-is-built" aria-label="Permalink to &quot;How it is built&quot;">​</a></h1><p>Tranqui is open source: you can check that it does what it says on <a href="https://github.com/fsoftt/Tranqui" target="_blank" rel="noreferrer">GitHub</a>.</p><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><div class="stack-grid"><div><strong>App</strong>.NET MAUI for Android, MVVM with CommunityToolkit</div><div><strong>Backend</strong>.NET 10, ASP.NET Core minimal APIs, MediatR 12, FluentValidation</div><div><strong>Data</strong>PostgreSQL 17 with EF Core 10</div><div><strong>Accounts</strong>Firebase Authentication, tokens validated on the server</div><div><strong>Cryptography</strong>HMAC-SHA256, AES-256-GCM, HKDF</div><div><strong>Testing</strong>xUnit v3, Testcontainers, architecture tests</div><div><strong>Deployment</strong>Docker Compose and Caddy with automatic HTTPS</div><div><strong>CI</strong>GitHub Actions: backend, Docker image and Android app</div></div><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><strong>Domain-Driven Design:</strong> the domain (numbers, reputation, accounts) depends on nothing external.</li><li><strong>Clean Architecture with vertical slices:</strong> each feature keeps its command or query, validator and handler together.</li><li><strong>Architecture tests</strong> that fail if a layer depends on one it must not.</li><li><strong>App.Core:</strong> all the app&#39;s logic (deciding what to do with a call, the session, the ViewModels) is plain .NET and tested without an emulator.</li></ul><h2 id="privacy-by-design" tabindex="-1">Privacy by design <a class="header-anchor" href="#privacy-by-design" aria-label="Permalink to &quot;Privacy by design&quot;">​</a></h2><ul><li>The number is normalized (international E.164 format) and turned into a code in <strong>exactly one place</strong> in the code.</li><li>Numbers travel in request bodies, never in URLs, so they never end up in access logs.</li><li>Logs contain no numbers, names or emails.</li><li>Secret keys are never in the repository or the database, and can be rotated.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><a href="https://github.com/fsoftt/Tranqui/blob/main/LICENSE" target="_blank" rel="noreferrer">AGPL-3.0</a>: anyone can use, study and modify the code, and whoever offers a modified version as a service must publish their changes.</p>',10)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
